import{_ as o,o as a,c as r,ab as t}from"./chunks/framework.DfnUYNhO.js";const m=JSON.parse('{"title":"Prepare colaboração e acesso da equipe","description":"","frontmatter":{"title":"Prepare colaboração e acesso da equipe","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"05f448dda78b05027b84b2c03f08a15eb515aee05af79397a1596d7e40ec5d40","translationRevision":"8f5129b72983233db0bcad4df6cec2c45edd719e9ccc797a4e9001b625267700","order":30},"headers":[],"relativePath":"pt/user/cloud/collaboration.md","filePath":"pt/user/cloud/collaboration.md","lastUpdated":1795477225000}'),s={name:"pt/user/cloud/collaboration.md"};function i(n,e,c,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Prepare colaboração e acesso da equipe <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;Prepare colaboração e acesso da equipe {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Conceda a outro operador um papel definido, mantendo o controle do proprietário. O acesso remoto é fornecido pelo plugin instalável <strong>Remote Control</strong>, não por uma aba de configurações: você precisa de <a href="./account.html">login no Cloud</a>, de um backend compatível e do plugin instalado neste host. Comece com acesso somente de leitura e uma configuração fora de produção.</p><h2 id="configure-remote-access" tabindex="-1">Configure o acesso remoto <a class="header-anchor" href="#configure-remote-access" aria-label="Permalink to &quot;Configure o acesso remoto {#configure-remote-access}&quot;">​</a></h2><ol><li>Instale e habilite <code>tiktools.remote-control</code> e abra sua página <strong>Remote control</strong>.</li><li>Crie uma equipe e registre <strong>este PC</strong> como host com um rótulo de dispositivo reconhecível; inicie o vínculo de retransmissão e aguarde até que o status atinja <code>ready</code>.</li><li>Crie um convite e entregue seu token de uso único por um canal confiável. Um convite não é o mesmo que uma sessão ativa aprovada.</li><li>Revise a solicitação pendente e o papel solicitado. Aprove apenas o operador esperado; a concessão permanece <code>pendingHost</code> até que o vínculo do host a confirme.</li><li>Inspecione regularmente as concessões e os dispositivos. Revogue uma concessão quando o acesso não for mais necessário.</li></ol><p>Edição delegada de definições, adoção de uma definição como proprietário e aprovação de execução delegada são decisões distintas. Leia a origem salva, as ações referenciadas e as permissões na revisão específica. Uma prévia de definição sozinha não autoriza um efeito.</p><h2 id="prepare-a-controller-device" tabindex="-1">Prepare um dispositivo controlador <a class="header-anchor" href="#prepare-a-controller-device" aria-label="Permalink to &quot;Prepare um dispositivo controlador {#prepare-a-controller-device}&quot;">​</a></h2><p>No dispositivo controlador, entre com sua própria conta, registre-o como controlador e resgate o token do convite. Uma solicitação pendente aparecerá então para o proprietário. A busca por apelido exige um endpoint de backend implantado separadamente e pode estar indisponível no serviço atual. Não presuma que uma busca que falhou significa que a pessoa não tem conta nem substitua a seleção por um ID arbitrário.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>O fluxo entre duas contas (equipe, vínculo do host, convite, aprovação, comando de leitura e revogação) foi verificado com um backend local. As abas de colaboração/equipes nas configurações foram removidas; o serviço nativo de colaboração não tem interface web nesta versão. O comportamento de retransmissão/NAT em produção, a busca por apelido e a operação LIVE entre dois PCs não estão comprovados aqui. Um vínculo pronto sozinho não comprova a aplicação de permissões de ponta a ponta para sua ação pretendida.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para concessões desatualizadas, revogue o acesso e revise-o novamente após a atualização do vínculo. Para comandos não confirmados, inspecione o resultado registrado antes de tentar novamente. Pare o vínculo ou revogue o acesso ao encerrar uma sessão. Mantenha tokens de convite e credenciais fora de <a href="./../preferences/troubleshooting.html">relatórios de diagnóstico</a> públicos.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Cada comando remoto passa pelo controle de capacidades do host (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>); o plugin nunca recebe uma Control API nem um token completo. Um transporte ativo ou a participação em uma equipe não concedem acesso nativo sozinhos. Observer é de leitura; moderator acrescenta controles selecionados, automationEditor edição selecionada e custom exige política explícita revisada. Nenhum concede scripts/efeitos irrestritos. Veja <a href="./../../developer/collaboration.html#operational-details">papéis e confirmação</a> e <a href="./../../developer/transports.html">transports</a> para o limite atual.</p>',14)])])}const v=o(s,[["render",i]]);export{m as __pageData,v as default};
